/* Step 1: Validate inputs and configuration */
if ((st_input.predicted == NULL) || (st_input.measured == NULL)) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

if ((st_input.enable != 0) && (st_input.enable != 1)) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

if ((st_config.max_rejects < 1U) || (st_config.max_rejects > 20U)) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

if (!isfinite(st_config.accept_rad) || !isfinite(st_config.reject_rad)) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

if ((st_config.accept_rad < 0.0) || (st_config.accept_rad >= st_config.reject_rad) || (st_config.reject_rad > ADCS_PI)) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

/* Step 2: Handle Disabled state */
if (st_input.enable == 0) {
    st_output.mode = ST_ACCEPT;
    st_output.rejects = 0;
    st_output.innovation_rad = 0.0;
    st_output.axis = (adcs_vec3_t){0.0, 0.0, 1.0};
    return;
}

/* Step 3: Normalize quaternions */
adcs_quat_t pred_norm, meas_norm;
if (adcs_quat_normalize(st_input.predicted, &pred_norm) != ADCS_OK) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}
if (adcs_quat_normalize(st_input.measured, &meas_norm) != ADCS_OK) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_config.max_rejects + 1;
    return;
}

/* Step 4: Compute innovation angle using abs_dot */
double cos_half_angle = adcs_quat_abs_dot(&meas_norm, &pred_norm);
if (cos_half_angle > 1.0) cos_half_angle = 1.0;
if (cos_half_angle < -1.0) cos_half_angle = -1.0; // Should not happen with abs, but safe guard
double innovation_rad = 2.0 * acos(cos_half_angle);

st_output.innovation_rad = innovation_rad;

/* Step 5: Decision Logic with Hysteresis */
st_mode_t new_mode = st_state.mode;
unint32 new_rejects = st_state.rejects;

if (innovation_rad <= st_config.accept_rad) {
    new_mode = ST_ACCEPT;
    new_rejects = 0;
} else if (innovation_rad >= st_config.reject_rad) {
    new_mode = ST_REJECT;
    new_rejects++;
    if (new_rejects > st_config.max_rejects) {
        new_mode = ST_FAULT;
        new_rejects = st_config.max_rejects + 1;
    }
} else {
    // Hysteresis band: preserve prior decision
    if (st_state.mode == ST_FAULT) {
        new_mode = ST_FAULT;
        // Rejects remain latched
    } else {
        new_mode = st_state.mode;
        new_rejects = st_state.rejects;
    }
}

/* Update global state */
st_state.mode = new_mode;
st_state.rejects = new_rejects;

/* Step 6: Output Assignment */
st_output.mode = new_mode;
st_output.rejects = new_rejects;

/* Step 7: Publish Relative Rotation Axis */
// Calculate innovation quaternion vector part for axis extraction
// q_inn = meas * conj(pred)
adcs_quat_t q_conj_pred = adcs_quat_conjugate(&pred_norm);
adcs_quat_t q_inn = adcs_quat_multiply(&meas_norm, &q_conj_pred);

adcs_vec3_t vec_part = {q_inn.x, q_inn.y, q_inn.z};
double norm_v = adcs_vec3_norm(&vec_part);

if (norm_v > ADCS_EPS_NORM) {
    adcs_vec3_t norm_axis;
    adcs_vec3_normalize(&vec_part, ADCS_EPS_NORM, &norm_axis);
    st_output.axis = norm_axis;
} else {
    st_output.axis = (adcs_vec3_t){0.0, 0.0, 1.0};
}

