    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    return;
}

int valid_config = 1;
if (!isfinite(st_config.accept_rad) || !isfinite(st_config.reject_rad)) {
    valid_config = 0;
} else if (!(0.0 <= st_config.accept_rad && st_config.accept_rad < st_config.reject_rad && st_config.reject_rad <= ADCS_PI)) {
    valid_config = 0;
}

if (!isfinite(st_config.max_rejects) || ((unint32)st_config.max_rejects < 1U) || ((unint32)st_config.max_rejects > 20U)) {
    valid_config = 0;
}

if (!isfinite(st_input.enable) || ((unint32)st_input.enable != 0U && (unint32)st_input.enable != 1U)) {
    valid_config = 0;
}

if (!valid_config) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    return;
}

adcs_quat_t q_pred_norm, q_meas_norm;
if (adcs_quat_normalize(st_input.predicted, &q_pred_norm) != ADCS_OK) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    return;
}
if (adcs_quat_normalize(st_input.measured, &q_meas_norm) != ADCS_OK) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    return;
}

/* 2. Innovation Angle Calculation */
adcs_quat_t q_conj_pred = adcs_quat_conjugate(&q_pred_norm);
adcs_quat_t q_delta = adcs_quat_multiply(&q_conj_pred, &q_meas_norm);

double abs_dot = fabs(q_delta.w);
if (abs_dot > 1.0) abs_dot = 1.0;
if (abs_dot < -1.0) abs_dot = -1.0;

double angle = 2.0 * acos(abs_dot);
if (!isfinite(angle)) {
     st_state.mode = ST_FAULT;
     st_output.mode = ST_FAULT;
     return;
}

/* 3. Decision Logic with Hysteresis */
// If already latched in FAULT, stay in FAULT
if (st_state.mode == ST_FAULT) {
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = angle;
    st_output.axis = (adcs_vec3_t){0, 0, 0};
    return;
}

unint32 max_rej = (unint32)st_config.max_rejects;
double accept_rad = st_config.accept_rad;
double reject_rad = st_config.reject_rad;

st_output.innovation_rad = angle;

if (st_input.enable == 0) {
    // Disabled: Always ACCEPT
    st_state.mode = ST_ACCEPT;
    st_state.rejects = 0;
    st_output.mode = ST_ACCEPT;
    st_output.rejects = 0;
} else {
    // Enabled logic
    if (angle <= accept_rad) {
        // Accept region
        st_state.mode = ST_ACCEPT;
        st_state.rejects = 0;
        st_output.mode = ST_ACCEPT;
        st_output.rejects = 0;
    } else if (angle >= reject_rad) {
        // Reject region
        st_state.rejects++;
        if (st_state.rejects >= max_rej) {
            st_state.mode = ST_FAULT;
            st_output.mode = ST_FAULT;
        } else {
            st_state.mode = ST_REJECT;
            st_output.mode = ST_REJECT;
        }
        st_output.rejects = st_state.rejects;
    } else {
        // Hysteresis band: Preserve prior state
        st_output.mode = st_state.mode;
        st_output.rejects = st_state.rejects;
    }
}

/* 4. Publish Relative Rotation Axis */
if (st_output.mode == ST_ACCEPT) {
    // The rotation axis is proportional to the vector part of the delta quaternion
    adcs_vec3_t raw_axis = (adcs_vec3_t){q_delta.x, q_delta.y, q_delta.z};

    // Normalize the axis
    adcs_status_t stat = adcs_vec3_normalize(&raw_axis, FLT64_ZERO, &st_output.axis);
    if (stat != ADCS_OK) {
        st_output.axis = (adcs_vec3_t){0, 0, 0};
    }
} else {
    st_output.axis = (adcs_vec3_t){0, 0, 0};
}

